package handlers

import (
	"html/template"
	"net/http"
	"net/url"
	"regexp"
	"strings"

	"github.com/go-chi/chi/v5"
)

// inviteLinkCodePattern matches a well-formed invite code as generated by
// generateInviteCode (8 characters from inviteCodeAlphabet). The landing page
// only ever echoes a code that matches, so nothing else can be reflected.
var inviteLinkCodePattern = regexp.MustCompile(`^[A-HJ-NP-Z2-9]{8}$`)

// hostPattern is a conservative hostname[:port] check for the fallback origin
// derived from the Host header.
var hostPattern = regexp.MustCompile(`^[A-Za-z0-9.-]+(:[0-9]{1,5})?$`)

var joinPageTmpl = template.Must(template.New("join").Parse(`<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex">
<title>Join on OpenFamily</title>
<style>
body{font-family:system-ui,sans-serif;margin:0;padding:24px;background:#f6f7f9;color:#1b1f24}
main{max-width:30rem;margin:8vh auto 0;background:#fff;border-radius:16px;padding:24px;box-shadow:0 1px 4px rgba(0,0,0,.12)}
h1{font-size:1.4rem;margin-top:0}
.code{font-size:2rem;font-weight:800;letter-spacing:.3rem;text-align:center;margin:16px 0}
a.btn{display:block;text-align:center;background:#1a73e8;color:#fff;text-decoration:none;padding:14px;border-radius:999px;font-weight:600}
ol{padding-left:1.2rem}
small{color:#5f6770}
@media (prefers-color-scheme:dark){body{background:#101317;color:#e6e8eb}main{background:#1a1f25}small{color:#9aa3ad}}
</style>
</head>
<body>
<main>
{{if .Code}}
<h1>You are invited to join a family on OpenFamily</h1>
<p>OpenFamily is a private, self-hosted family location app. Someone on this server invited you.</p>
<div class="code" aria-label="Invite code">{{.Code}}</div>
<p><a class="btn" href="{{.AppLink}}">Open in the OpenFamily app</a></p>
<ol>
<li>Install the OpenFamily Android app if you have not already.</li>
<li>Tap the button above. The app fills in this server and your invite code.</li>
<li>If the button does nothing, open the app, enter the server <strong>{{.Server}}</strong> and the code above.</li>
</ol>
<small>The invite expires and can only be used a limited number of times. Never share it with people you do not know.</small>
{{else}}
<h1>This invite link is not valid</h1>
<p>Ask the person who invited you to send a new link.</p>
{{end}}
</main>
</body>
</html>`))

// joinPageData is what the landing page template renders.
type joinPageData struct {
	Code    string
	Server  string
	AppLink template.URL
}

// publicOrigin returns the origin clients should use to reach this server: the
// configured PublicBaseURL when set, else derived from the request
// (X-Forwarded-Proto is honoured only to pick http vs https).
func (s *Server) publicOrigin(r *http.Request) string {
	if base := strings.TrimRight(strings.TrimSpace(s.PublicBaseURL), "/"); base != "" {
		return base
	}
	host := r.Host
	if !hostPattern.MatchString(host) {
		return ""
	}
	scheme := "https"
	if r.TLS == nil && r.Header.Get("X-Forwarded-Proto") == "http" {
		scheme = "http"
	}
	return scheme + "://" + host
}

// JoinLanding serves the public GET /join/{code} landing page. It explains the
// invite and deep-links into the app via openfamily://join?server=...&code=....
// It is deliberately static: it never queries the database, so it cannot be
// used to probe which codes exist, and it echoes only a well-formed code.
func (s *Server) JoinLanding(w http.ResponseWriter, r *http.Request) {
	code := normalizeCode(chi.URLParam(r, "code"))
	server := s.publicOrigin(r)
	data := joinPageData{}
	status := http.StatusOK
	if inviteLinkCodePattern.MatchString(code) && server != "" {
		q := url.Values{}
		q.Set("server", server)
		q.Set("code", code)
		data = joinPageData{
			Code:    code,
			Server:  server,
			AppLink: template.URL("openfamily://join?" + q.Encode()),
		}
	} else {
		status = http.StatusNotFound
	}
	h := w.Header()
	h.Set("Content-Type", "text/html; charset=utf-8")
	h.Set("Cache-Control", "no-store")
	h.Set("Referrer-Policy", "no-referrer")
	h.Set("X-Content-Type-Options", "nosniff")
	h.Set("Content-Security-Policy", "default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'")
	w.WriteHeader(status)
	_ = joinPageTmpl.Execute(w, data)
}
